import java.nio.file.*;import java.util.*;import javax.tools.*;import com.sun.source.util.JavacTask;
class ParseJava {public static void main(String[] args)throws Exception {JavaCompiler c=ToolProvider.getSystemJavaCompiler();DiagnosticCollector<JavaFileObject> ds=new DiagnosticCollector<>();StandardJavaFileManager fm=c.getStandardFileManager(ds,null,null);List<String>files=new ArrayList<>();Files.walk(Path.of(args[0])).filter(p->p.toString().endsWith(".java")).forEach(p->files.add(p.toString()));JavacTask task=(JavacTask)c.getTask(null,fm,ds,List.of("-proc:none"),null,fm.getJavaFileObjectsFromStrings(files));task.parse();for(var d:ds.getDiagnostics())System.out.println(d);if(ds.getDiagnostics().stream().anyMatch(d->d.getKind()==Diagnostic.Kind.ERROR))System.exit(1);System.out.println("PARSED: "+files.size()+" Java files; no syntax errors (not Android type checking).");}}
